import { test, expect } from '@playwright/test';

test.describe('Image Alt Text Accessibility', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/images');
  });

  test('should display descriptive alt text for all images', async ({ page }) => {
    // Verify all images have alt attributes
    const images = page.locator('[data-testid="image"]');
    await expect(images).toHaveCount(5);

    // Verify each image has non-empty alt text
    const altTexts = await page.locator('[data-testid="image"]').evaluate((el) => {
      return el.getAttribute('alt');
    });
    expect(altTexts).not.toBeEmpty();

    // Verify alt text is descriptive and not empty
    const altTextsArray = await altTexts.split('\n');
    for (const altText of altTextsArray) {
      expect(altText).toBeTruthy();
      expect(altText).toBeGreaterThan(0);
    }

    // Verify alt text is not just whitespace
    const nonWhitespaceAltTexts = altTextsArray.filter((altText) => altText.trim().length > 0);
    expect(nonWhitespaceAltTexts.length).toBeGreaterThan(0);

    // Verify alt text is not empty
    const nonEmptyAltTexts = altTextsArray.filter((altText) => altText.trim().length > 0);
    expect(nonEmptyAltTexts.length).toBeGreaterThan(0);

    // Verify alt text is not just a single word
    const multiWordAltTexts = nonEmptyAltTexts.filter((altText) => altText.split(' ').length > 1);
    expect(multiWordAltTexts.length).toBeGreaterThan(0);
  });

  test('should not display alt text for images without content', async ({ page }) => {
    // Navigate to a page with empty images
    await page.goto('/empty-images');

    // Verify all images have alt attributes
    const images = page.locator('[data-testid="image"]');
    await expect(images).toHaveCount(3);

    // Verify alt text is empty for images without content
    const altTexts = await page.locator('[data-testid="image"]').evaluate((el) => {
      return el.getAttribute('alt');
    });
    const emptyAltTexts = altTexts.filter((altText) => altText.trim().length === 0);
    expect(emptyAltTexts.length).toBe(3);

    // Verify alt text is not just whitespace
    const nonWhitespaceEmptyAltTexts = emptyAltTexts.filter((altText) => altText.trim().length > 0);
    expect(nonWhitespaceEmptyAltTexts.length).toBe(0);

    // Verify alt text is not just a single word
    const multiWordEmptyAltTexts = emptyAltTexts.filter((altText) => altText.split(' ').length > 1);
    expect(multiWordEmptyAltTexts.length).toBe(0);
  });
});
